
import type { MoneyValue } from './MoneyValue.js';

/** One credited invoice line, with the discount and tax share Flint derived from the source line. */ export type CreditNoteLine = { "credit_note_line_id": string; "description": string; "discount_money": MoneyValue; /** The invoice snapshot line this corrects. */ "invoice_line_item_id": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quantity"?: string; "subtotal_money": MoneyValue; "tax_money": MoneyValue; /** What this line credits, discount and tax included. */ "total_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; };
